actions.script:
import org.moqui.agent.AgentSkillSupport
AgentSkillSupport.ensureSkillLookupData(ec)
Set<String> userGroups = (ec.user.userGroupIdSet ?: []) as Set<String> if (!userGroups.intersect(['ADMIN', 'MCP_INDEX_ADMIN'] as Set<String>)) { ec.message.addError("Access denied: refresh#AgentSkills requires ADMIN or MCP_INDEX_ADMIN") return }
skillList = [] skillCount = 0 createdCount = 0 updatedCount = 0 skippedCount = 0 indexedCount = 0
List<File> skillFiles = AgentSkillSupport.listSkillFiles(ec, componentNameList) skillFiles.each { File skillFile -> Map skillData = AgentSkillSupport.parseSkillFile(skillFile) if (!skillData?.skillId || !skillData?.artifactName) { skippedCount++ return }
Map upsertValues = [ skillId: skillData.skillId, artifactName: skillData.artifactName, artifactTypeEnumId: skillData.artifactTypeEnumId ?: 'AT_OTHER', artifactGroupId: skillData.artifactGroupId ?: 'McpRuntimeServices', skillTypeEnumId: skillData.skillTypeEnumId ?: 'AGSKL_SYSTEM', domainName: skillData.domainName ?: '', title: skillData.title ?: skillData.skillId, description: skillData.description ?: '', componentName: skillData.componentName ?: '', skillLocation: skillData.skillLocation ?: '', skillPath: skillData.skillPath ?: '', statusId: skillData.statusId ?: 'SkillActive', frontmatterJson: skillData.frontmatterJson ?: '{}', bodyText: skillData.bodyText ?: '', searchText: skillData.searchText ?: '', contentHash: skillData.contentHash ?: '', lastIndexedDate: ec.user.nowTimestamp ]
def existing = ec.entity.find('moqui.agent.AgentSkillRegister') .condition('skillId', skillData.skillId) .useCache(false) .one() if (existing) { if (existing.contentHash != upsertValues.contentHash || existing.skillLocation != upsertValues.skillLocation || existing.title != upsertValues.title) { existing.setAll(upsertValues).update() updatedCount++ } else { skippedCount++ } } else { Map createValues = new LinkedHashMap(upsertValues) if (!createValues.agentSkillRegisterId) { createValues.agentSkillRegisterId = java.util.UUID.randomUUID().toString() } ec.entity.makeValue('moqui.agent.AgentSkillRegister').setAll(createValues).create() createdCount++ }
def artifactGroupMember = ec.entity.find('moqui.security.ArtifactGroupMember') .condition('artifactGroupId', upsertValues.artifactGroupId) .condition('artifactName', upsertValues.artifactName) .condition('artifactTypeEnumId', upsertValues.artifactTypeEnumId) .useCache(false) .one() if (!artifactGroupMember) { ec.entity.makeValue('moqui.security.ArtifactGroupMember').setAll([ artifactGroupId: upsertValues.artifactGroupId, artifactName: upsertValues.artifactName, artifactTypeEnumId: upsertValues.artifactTypeEnumId, nameIsPattern: 'N', inheritAuthz: 'Y' ]).create() }
skillList << upsertValues }
skillCount = skillList.size()
if (reindex && skillCount > 0) { Map indexResult = ec.service.sync().name('org.moqui.agent.AgentSkillServices.index#AgentSkillDocuments') .parameters([clusterName: clusterName]) .call() indexedCount = (indexResult?.documentsIndexed ?: 0) as Integer }

import org.moqui.agent.AgentToolSupport
import org.moqui.entity.EntityCondition

int effectiveLimit = Math.max(1, (limit ?: 100) as Integer)
def find = ec.entity.find('moqui.agent.AgentSkillRegister')
        .orderBy('domainName')
        .orderBy('title')
        .limit(effectiveLimit)
if (skillTypeEnumId) find.condition('skillTypeEnumId', skillTypeEnumId)
if (domainName) find.condition('domainName', domainName)
if (componentName) find.condition('componentName', componentName)
if (queryText) find.condition('searchText', EntityCondition.LIKE, "%${queryText}%")
def rows = find.list() ?: []
skillList = []
rows.each { row ->
    if (AgentToolSupport.checkArtifactAccess(ec, row.artifactTypeEnumId as String ?: 'AT_OTHER', 'AUTHZA_VIEW', row.artifactName as String ?: '')) {
        skillList << row.getPlainValueMap(0)
    }
}
skillCount = skillList.size()

import org.moqui.agent.AgentToolSupport

def skillValue = ec.entity.find('moqui.agent.AgentSkillRegister')
        .condition('skillId', skillId)
        .useCache(true)
        .one()
if (!skillValue) {
    ec.message.addError("Skill not found")
    return
}
authorized = AgentToolSupport.checkArtifactAccess(ec, skillValue.artifactTypeEnumId as String ?: 'AT_OTHER', 'AUTHZA_VIEW', skillValue.artifactName as String ?: '')
if (!authorized) {
    ec.message.addError("Skill not found")
    return
}

skill = skillValue.getPlainValueMap(0)
skill.frontmatter = skillValue.frontmatterJson ? new groovy.json.JsonSlurper().parseText(skillValue.frontmatterJson as String) : [:]

int effectiveLimit = Math.max(1, (limit ?: 5) as Integer)
Map searchResult = ec.service.sync().name('org.moqui.agent.AgentSkillServices.search#AgentSkills')
        .parameters([
                queryText: queryText,
                domainName: domainName,
                skillTypeEnumId: skillTypeEnumId,
                limit: effectiveLimit,
                clusterName: 'default'
        ]).call()

List<Map> candidates = (searchResult?.skillList instanceof List) ? (List<Map>) searchResult.skillList : []
if (!candidates) {
    Map listResult = ec.service.sync().name('org.moqui.agent.AgentSkillServices.list#AgentSkills')
            .parameters([
                    queryText: queryText,
                    domainName: domainName,
                    skillTypeEnumId: skillTypeEnumId,
                    limit: effectiveLimit
            ]).call()
    candidates = (listResult?.skillList instanceof List) ? (List<Map>) listResult.skillList : []
}

candidateSkillList = candidates
candidateSkillCount = candidates.size()
needsMoreContext = candidateSkillCount == 0
fallbackRecommended = candidateSkillCount == 0

if (candidateSkillCount > 0) {
    selectedSkill = candidates[0]
    if (candidateSkillCount > 1) {
        reason = "Multiple authorized skills matched; using the first candidate as the best available default."
    } else {
        reason = "Single authorized skill matched."
    }
} else {
    selectedSkill = null
    reason = "No authorized skill matched the query; prompt-first fallback may be required."
}
